   HAULER_PAYM_CLASS_CD                VARCHAR(5)      COMMENT 'This Payment Code classifies Trackingids, classification depends on the carrier. Depending on the code Lidl Digital has to pay a different amount of money to the carrier.',
   PACK_HEIGHT_MEAS                    NUMERIC(38,5)   COMMENT 'Package_2 height',
