   PACK_VOLUME_UOM_SID                 NUMERIC         COMMENT 'Package_2 volume unit_2 of measure',
   WEIGHT_CLASS_CD                     VARCHAR(50)     COMMENT 'A code for weight classification',
   VOLUME_CLASS_CD                     VARCHAR(50)     COMMENT 'A code for volume classification',
   DELIVERY_ORDER_SID                  NUMERIC         COMMENT 'The unique identifier (surrogate key) for delivery order ',
   DELIV_PROD_QTY                      NUMERIC(38,5)   COMMENT 'Total quantity of delivered products within the given package.',
   PACK_MATERIAL_NR                    VARCHAR(20)     COMMENT 'The packaging material number (e..g 420000026,  420000028)',
